package com.example.demo.api;
import com.example.demo.model.*;import com.example.demo.repo.*;import com.example.demo.security.Sessions;import tools.jackson.databind.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/scans") public class ScanController{
 private final CropRepo crops;private final ScanRepo scans;private final ObjectMapper json=new ObjectMapper();@Value("${farmmind.ai-url:http://localhost:8000}")private String aiUrl;@Value("${farmmind.upload-dir:uploads}")private String uploadDir;
 public ScanController(CropRepo c,ScanRepo s){crops=c;scans=s;}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> scan(@RequestHeader(value="Authorization",required=false)String auth,@RequestParam("image")MultipartFile image,@RequestParam(value="cropId",required=false)Long cropId){Long uid=Sessions.user(auth);if(uid==null)return ResponseEntity.status(401).body(Map.of("error","Bearer token required"));if(image.isEmpty()||image.getSize()>10_000_000)return ResponseEntity.badRequest().body(Map.of("error","Provide a leaf image under 10 MB"));Crop crop=null;if(cropId!=null)crop=crops.findByIdAndFarmOwnerId(cropId,uid).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Crop not found"));try{String boundary="FarmMind"+UUID.randomUUID().toString().replace("-","");byte[] data=image.getBytes();byte[] head=("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"leaf\"\r\nContent-Type: "+Optional.ofNullable(image.getContentType()).orElse("image/jpeg")+"\r\n\r\n").getBytes();byte[] tail=("\r\n--"+boundary+"--\r\n").getBytes();byte[] body=new byte[head.length+data.length+tail.length];System.arraycopy(head,0,body,0,head.length);System.arraycopy(data,0,body,head.length,data.length);System.arraycopy(tail,0,body,head.length+data.length,tail.length);var request=java.net.http.HttpRequest.newBuilder(URI.create(aiUrl+"/predict")).timeout(java.time.Duration.ofSeconds(45)).header("Content-Type","multipart/form-data; boundary="+boundary).POST(java.net.http.HttpRequest.BodyPublishers.ofByteArray(body)).build();var response=HttpClient.newHttpClient().send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)return ResponseEntity.status(response.statusCode()).contentType(MediaType.APPLICATION_JSON).body(response.body());JsonNode out=json.readTree(response.body());if(!out.path("supported").asBoolean(true))return ResponseEntity.ok(out);if(crop!=null){ScanHistory record=new ScanHistory();record.crop=crop;Path dir=Path.of(uploadDir).toAbsolutePath().normalize();Files.createDirectories(dir);String ext="image/png".equalsIgnoreCase(image.getContentType())?".png":"image/webp".equalsIgnoreCase(image.getContentType())?".webp":".jpg";Path saved=dir.resolve(UUID.randomUUID()+ext).normalize();if(!saved.startsWith(dir))throw new IllegalStateException("Invalid scan path");Files.write(saved,data);record.imagePath=saved.toString();record.predictedDisease=out.path("predicted_disease").asText("Uncertain");record.confidence=out.path("confidence").asDouble();record.recommendations=out.path("preventive_actions").toString();scans.save(record);}return ResponseEntity.ok(out);}catch(HttpTimeoutException e){return ResponseEntity.status(504).body(Map.of("error","AI service timed out"));}catch(ConnectException e){return ResponseEntity.status(503).body(Map.of("error","AI service is unavailable; no diagnosis was generated"));}catch(Exception e){return ResponseEntity.status(502).body(Map.of("error","AI service could not analyze this image"));}}
 @GetMapping("/{cropId}") public List<Map<String,Object>> history(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable Long cropId){Long uid=Sessions.user(auth);if(uid==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return scans.findByCropIdAndCropFarmOwnerIdOrderByScanDateDesc(cropId,uid).stream().map(x->Map.<String,Object>of("id",x.id,"cropId",x.crop.id,"predictedDisease",x.predictedDisease,"confidence",x.confidence,"scanDate",x.scanDate,"recommendations",x.recommendations==null?"":x.recommendations)).toList();}
}





